func (t *memoTable) markSeen(pos, r int) bool {
	i := pos*t.stride + r
	w, b := i>>6, uint64(1)<<(i&63)
	if strconv.IntSize == 32 {
		w, b = seenBit(pos, r, t.stride)
	}
	if w >= len(t.seen) {
		if strconv.IntSize == 32 {
			seen := make([]uint64, seenCapacity(len(t.seen), w))
			copy(seen, t.seen)
			t.seen = seen
		} else {
			t.seen = append(t.seen, make([]uint64, max(w+1-len(t.seen), len(t.seen), 64))...)
		}
	}
	if t.seen[w]&b != 0 {
		return false
	}
	t.seen[w] |= b
	return true
}

// markSparseSeen records only visited per-rule regions, with page allocation
// batched to keep the directory savings from adding one allocation per page.
func (t *memoTable) markSparseSeen(pos, r int) bool {
	page := t.cachedSeenPage(pos, r)
	if page == nil {
		page = t.sparsePage(pos, r)
	}
	return markSeenPage(page, pos)
}

// cachedSeenPage and markSeenPage inline into firstCall. Keeping allocation
// separate avoids another function call when a rule remains in its last page.
func (t *memoTable) cachedSeenPage(pos, r int) *[16]uint64 {
	if r < len(t.pages) {
		dir := &t.pages[r]
		if dir.at == pos>>10 {
			return dir.last
		}
	}
	return nil
}

func markSeenPage(page *[16]uint64, pos int) bool {
	w, b := (pos>>6)&15, uint64(1)<<(pos&63)
	first := page[w]&b == 0
	page[w] |= b
	return first
}

// sparsePage handles directory growth and page allocation off the hot path.
func (t *memoTable) sparsePage(pos, r int) *[16]uint64 {
	if len(t.pages) != t.stride {
		t.pages = make([]seenRulePages, t.stride)
	}
	dir := &t.pages[r]
	at := pos >> 10
	page := dir.last
	if page == nil || dir.at != at {
		pages := dir.pages
		if at >= len(pages) {
			if at < cap(pages) {
				pages = pages[:at+1]
			} else {
				grown := make([]*[16]uint64, at+1, max(at+1, 2*cap(pages), 4))
				copy(grown, pages)
				pages = grown
			}
			dir.pages = pages
		}
		page = pages[at]
		if page == nil {
			page = t.bitPages.alloc()
			pages[at] = page
		}
		dir.last, dir.at = page, at
	}
	return page
}

// seenBit uses a wide intermediate on 32-bit hosts: the bit number can
// exceed MaxInt while its word index and backing array remain addressable.
func seenBit(pos, r, stride int) (int, uint64) {
	if strconv.IntSize == 32 {
		i := uint64(pos)*uint64(stride) + uint64(r)
		w := i >> 6
		if w >= uint64(^uint(0))/8 {
			panic(fatal{errors.New("deferred memoization bitset size overflows uintptr")})
		}
		return int(w), uint64(1) << (i & 63)
	}
	i := pos*stride + r
	return i >> 6, uint64(1) << (i & 63)
}

// seenCapacity bounds geometric growth before the 32-bit exact allocation.
func seenCapacity(used, word int) int {
	return max(word+1, min(2*used, int(^uint(0)/8)), 64)
}

